const panels=[...root.querySelectorAll('[data-scene]')],chapterButtons=[...root.querySelectorAll('[data-chapter]')];const desk=root.querySelector('.desk-world'),dark=root.querySelector('.dark-world'),warm=root.querySelector('.warm-world'),shadow=root.querySelector('.product-shadow'),orbits=root.querySelector('.orbit-lines'),label=root.querySelector('#scene-label');
